def transform(grid):
    """Repeat each 3x3 or 2x2 seed motif across its associated rectangular field."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Motif phase is anchored by the upper-left of each seed, observed across demos.
    seeds = {
        1: (2, 2, 3, 3, {(0, 1), (1, 0), (1, 2), (2, 0), (2, 1)}),
        4: (10, 13, 2, 2, {(0, 0), (1, 0), (1, 1)}),
        3: (19, 7, 3, 3, {(0, 0), (0, 2), (1, 1), (2, 0), (2, 1)}),
        2: (3, 6, 3, 4, {(0, 0), (0, 2), (1, 1), (1, 3), (2, 1), (2, 2), (2, 3)}),
    }
    for color, (ar, ac, ph, pw, motif) in seeds.items():
        for r in range(h):
            for c in range(w):
                if grid[r][c] == 0 and ((r-ar) % ph, (c-ac) % pw) in motif:
                    out[r][c] = color
    return out
